package com.clan.recruitment;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ClanRecruitmentConfig.GROUP)
public interface ClanRecruitmentConfig extends Config
{
	String GROUP = "clanrecruitment";

	@ConfigItem(
		keyName = "enabled",
		name = "Enable hiding of players",
		description = "Hide players when their Recruit menu option is clicked",
		position = 0
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hiddenPlayers",
		name = "Hidden players list",
		description = "Persisted list of hidden player names"
	)
	default String hiddenPlayers()
	{
		return "";
	}
	@ConfigItem(
		keyName = "webhookUrl",
		name = "Webhook URL (optional)",
		description = "Optional URL to send recruitment acceptance events to"
	)
	default String webhookUrl()
	{
		return "";
	}
}

package com.clan.recruitment;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.Collection;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class ClanRecruitmentPanel extends PluginPanel
{
	private final ClanRecruitmentPlugin plugin;
	private final ClanRecruitmentConfig config;

	private final JButton toggleButton = new JButton();
	private final JTextArea hiddenUsersArea = new JTextArea();
	private final JButton clearButton = new JButton("Clear all");

	@Inject
	public ClanRecruitmentPanel(ClanRecruitmentPlugin plugin, ClanRecruitmentConfig config)
	{
		super(false);

		this.plugin = plugin;
		this.config = config;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		toggleButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		toggleButton.setForeground(Color.WHITE);
		toggleButton.setFocusPainted(false);
		toggleButton.addActionListener(e -> plugin.setFeatureEnabled(!config.enabled()));
		updateToggleButtonText(config.enabled());

		hiddenUsersArea.setEditable(false);
		hiddenUsersArea.setLineWrap(true);
		hiddenUsersArea.setWrapStyleWord(true);

		hiddenUsersArea.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		hiddenUsersArea.setForeground(Color.WHITE);
		hiddenUsersArea.setCaretColor(Color.WHITE);
		hiddenUsersArea.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));

		JScrollPane scrollPane = new JScrollPane(hiddenUsersArea);
		scrollPane.setPreferredSize(new Dimension(220, 220));
		scrollPane.setBorder(
			BorderFactory.createTitledBorder(
				BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
				"Hidden usernames"
			)
		);

		scrollPane.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);

		clearButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		clearButton.setForeground(Color.WHITE);
		clearButton.setFocusPainted(false);
		clearButton.addActionListener(e -> plugin.clearHiddenPlayers());

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 6));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(toggleButton);

		add(top, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
		add(clearButton, BorderLayout.SOUTH);

		refresh(plugin.getHiddenPlayers());
	}

	private void updateToggleButtonText(boolean enabled)
	{
		toggleButton.setText(enabled ? "Disable hiding players" : "Enable hiding players");
	}

	public void refresh(Collection<String> names)
	{
		SwingUtilities.invokeLater(() ->
		{
			updateToggleButtonText(config.enabled());

			if (names.isEmpty())
			{
				hiddenUsersArea.setText("");
				return;
			}

			String text = names.stream()
				.sorted(String.CASE_INSENSITIVE_ORDER)
				.collect(Collectors.joining("\n"));

			hiddenUsersArea.setText(text);
			hiddenUsersArea.setCaretPosition(0);
		});
	}
}

package com.clan.recruitment;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Collection;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.Hooks;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@PluginDescriptor(
	name = "Clan Recruitment",
	description = "Hide players when Recruit is clicked",
	tags = {"clan", "recruit", "hide"}
)
public class ClanRecruitmentPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClanRecruitmentConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Hooks hooks;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClanRecruitmentPanel panel;

	@Inject
	private OkHttpClient okHttpClient;

	private NavigationButton navButton;

	private final Set<String> hiddenPlayers = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);

	private final Hooks.RenderableDrawListener drawListener = this::shouldDraw;

	@Provides
	ClanRecruitmentConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClanRecruitmentConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadHiddenPlayers();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Clan Recruitment")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		hooks.registerRenderableDrawListener(drawListener);
		panel.refresh(hiddenPlayers);
	}

	@Override
	protected void shutDown()
	{
		hooks.unregisterRenderableDrawListener(drawListener);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		hiddenPlayers.clear();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.enabled())
		{
			return;
		}

		if (!"Recruit".equalsIgnoreCase(event.getMenuOption()))
		{
			return;
		}

		if (event.getMenuEntry() == null || event.getMenuEntry().getPlayer() == null)
		{
			return;
		}

		Player player = event.getMenuEntry().getPlayer();
		String playerName = normalizeName(player.getName());

		if (playerName.isEmpty())
		{
			return;
		}

		if (hiddenPlayers.add(playerName))
		{
			saveHiddenPlayers();
			panel.refresh(hiddenPlayers);
			log.debug("Added hidden player: {}", playerName);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.enabled())
		{
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();

		String playerName = extractAcceptingPlayerName(message);

		if (playerName == null)
		{
			return;
		}

		log.debug("Detected invitation acceptance attempt from {}", playerName);

		String inviterName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		sendAcceptingInvitationWebhook(playerName, message, inviterName);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ClanRecruitmentConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("hiddenPlayers".equals(event.getKey()))
		{
			loadHiddenPlayers();
			panel.refresh(hiddenPlayers);
		}
		else if ("enabled".equals(event.getKey()))
		{
			panel.refresh(hiddenPlayers);
		}
	}

	boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		if (!(renderable instanceof Player))
		{
			return true;
		}

		if (!config.enabled())
		{
			return true;
		}

		Player player = (Player) renderable;
		String playerName = normalizeName(player.getName());

		if (playerName.isEmpty())
		{
			return true;
		}

		return !hiddenPlayers.contains(playerName);
	}

	void setFeatureEnabled(boolean enabled)
	{
		configManager.setConfiguration(ClanRecruitmentConfig.GROUP, "enabled", enabled);
		panel.refresh(hiddenPlayers);
	}

	void clearHiddenPlayers()
	{
		hiddenPlayers.clear();
		saveHiddenPlayers();
		panel.refresh(hiddenPlayers);
	}

	Collection<String> getHiddenPlayers()
	{
		return hiddenPlayers;
	}

	private void loadHiddenPlayers()
	{
		hiddenPlayers.clear();

		String raw = config.hiddenPlayers();

		if (raw == null || raw.trim().isEmpty())
		{
			return;
		}

		for (String part : raw.split("\\n"))
		{
			String name = normalizeName(part);

			if (!name.isEmpty())
			{
				hiddenPlayers.add(name);
			}
		}
	}

	private void saveHiddenPlayers()
	{
		String joined = hiddenPlayers.stream()
			.sorted(String.CASE_INSENSITIVE_ORDER)
			.collect(Collectors.joining("\n"));

		configManager.setConfiguration(
			ClanRecruitmentConfig.GROUP,
			"hiddenPlayers",
			joined
		);
	}

	private static String extractAcceptingPlayerName(String message)
	{
		if (message == null)
		{
			return null;
		}

		String suffix = " is attempting to accept your invitation!";

		if (!message.endsWith(suffix))
		{
			return null;
		}

		String playerName = normalizeName(
			message.substring(0, message.length() - suffix.length())
		);

		return playerName.isEmpty() ? null : playerName;
	}

	private void sendAcceptingInvitationWebhook(String playerName, String message, String inviterName)
	{
		String webhookUrl = config.webhookUrl();

		if (webhookUrl == null || webhookUrl.trim().isEmpty())
		{
			log.debug("No webhook URL configured, skipping webhook");
			return;
		}

		String inviterField = inviterName != null
			? "\"inviterName\":\"" + escapeJson(inviterName) + "\","
			: "\"inviterName\":null,";

		String json = "{"
			+ "\"type\":\"CLAN_INVITATION_ACCEPTING\","
			+ "\"playerName\":\"" + escapeJson(playerName) + "\","
			+ inviterField
			+ "\"message\":\"" + escapeJson(message) + "\""
			+ "}";

		Request request = new Request.Builder()
			.url(webhookUrl.trim())
			.post(RequestBody.create(
				MediaType.parse("application/json"),
				json
			))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to send webhook", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				response.close();
			}
		});
	}

	private static String escapeJson(String value)
	{
		return value
			.replace("\\", "\\\\")
			.replace("\"", "\\\"");
	}

	private static String normalizeName(String name)
	{
		if (name == null)
		{
			return "";
		}

		return name
			.replace('\u00A0', ' ')
			.trim();
	}

}

